    map, bumpMap: bump, bumpScale: opts.bumpScale ?? 0.07,
    color: opts.color ?? 0xffffff,
    roughness: opts.roughness ?? (style === 'metal' ? 0.34 : style === 'ice' ? 0.42 : 0.72),
    metalness: opts.metalness ?? (style === 'metal' ? 0.86 : style === 'ice' ? 0.12 : 0.04),
