  const tailA = makeTail(pelvis, { count: 7, length: 0.7, r: 0.45, taper: 0.88, mat: mats.skin, plateMat: mats.plate, plateScale: 0.7, x: -0.35, y: 0, z: 0.85, droop: -0.2, side: -0.08 });
