177:     this.active = true;
178:     this.hasStarted = true;
179:     this.ui?.showHUD(this);
180:     this.ui?.closeOverlays();
181:     this.updateObjective();
182:     this.ui?.toast(this.mode === 'battle' ? 'BATTLE START' : this.mode === 'sandbox' ? 'SANDBOX ONLINE' : 'FREE ROAM', 'info');
183:     this.audio.setWeather(this.mode === 'battle' ? (config.weather || 'rain') : (config.weather || 'clear'));
184:     if (this.mode === 'battle' && config.title) this.ui?.showTitle?.(config.title);
185:     // spawn roar
186:     setTimeout(() => {
