204:   update(dt) {
205:     if (!this.active || this.paused) return;
206:     dt = Math.min(dt, 0.05);
207:     this.time += dt;
208:     this.environment.update(dt, this.camera);
209:     this.city.update(dt, this.camera, this.monsters);
210: 
211:     // player intent
212:     const p = this.player;
213:     if (p && !p.dead && !this.spectate) {
214:       const move = this.input.getMove(this.input.yaw);
215:       p.intent.moveX = move.x;
216:       p.intent.moveZ = move.z;
217:       p.intent.run = this.input.run && !this.input.block;
218:       p.intent.block = this.input.block;
219:       p.intent.attack = null;
220:       p.intent.special = false;
221:       p.intent.dodge = false;
222:       p.intent.jump = false;
223:       p.intent.grab = false;
224:       p.intent.roar = false;
225:       p.intent.aimYaw = this.input.yaw;
226:       // soft lock nearest hostile in front for satisfying melee
227:       let best = null, bestD = 1e9;
228:       const camF = new THREE.Vector3(-Math.sin(this.input.yaw), 0, -Math.cos(this.input.yaw));
229:       for (const m of this.monsters) {
230:         if (m === p || m.dead || m.team === p.team) continue;
231:         const to = m.root.position.clone().sub(p.root.position).setY(0);
232:         const d = to.length();
233:         if (d < p.height * 2.2 && d < bestD) {
234:           to.normalize();
235:           if (to.dot(camF) > 0.1) { best = m; bestD = d; }
236:         }
237:       }
238:       const actions = this.input.consumeActions();
239:       for (const a of actions) {
240:         if (a === 'light' || a === 'heavy' || a === 'tail' || a === 'bite' || a === 'stomp') {
241:           if (best) p.intent.aimYaw = Math.atan2(-(best.root.position.x - p.root.position.x), -(best.root.position.z - p.root.position.z));
242:           p.intent.attack = a;
243:         } else if (a === 'special') { p.intent.special = true; if (best) p.intent.aimYaw = Math.atan2(-(best.root.position.x - p.root.position.x), -(best.root.position.z - p.root.position.z)); }
244:         else if (a === 'grab') p.intent.grab = true;
245:         else if (a === 'roar') p.intent.roar = true;
246:         else if (a === 'dodge') p.intent.dodge = true;
247:         else if (a === 'jump') p.intent.jump = true;
248:       }
249:       if (p.state.grabbed && this.input.keys.has('KeyG')) p.throwGrabbed?.();
250:     } else if (p) {
251:       p.intent.moveX = p.intent.moveZ = 0;
252:       p.intent.attack = null;
253:       p.intent.special = false;
254:       this.input.consumeActions();
255:     }
256: 
257:     for (const m of this.monsters) m.update(dt);
258:     this.effects.update(dt, this.camera);
259:     const target = this.player && !this.player.dead ? this.player : (this.monsters.find(m => !m.dead) || null);
260:     if (target) {
261:       if (this.spectate) this.cameraRig.spectate = true;
262:       this.cameraRig.update(dt, target, this.input, this.monsters);
263:     }
264:     // cinematic fov
265:     const wantFov = this.cameraRig.cinematic > 0 ? 46 : 56;
266:     this.camera.fov = damp(this.camera.fov, wantFov, 3, dt);
267:     this.camera.updateProjectionMatrix();
268: 
269:     if (this.introTimer > 0) {
270:       this.introTimer -= dt;
271:       if (this.introTimer <= 0) this.ui?.hideVersus?.();
272:     }
273:     this.checkEnd(dt);
274:     this.updateObjective();
275:     this.ui?.updateHUD?.(this, dt);
276:   }
277: 
278:   updateObjective() {
279:     if (this.mode === 'battle') {
280:       const enemies = this.monsters.filter(m => m.team !== (this.player?.team ?? 0) && !m.dead);
281:       const names = enemies.map(m => m.name.toUpperCase()).join(' + ');
282:       this.objective = enemies.length ? `SLAY ${names}` : 'HOSTILES ELIMINATED';
283:       this.subObjective = `HONG KONG // ${this.environment.weather.toUpperCase()} // ${this.environment.hour.toFixed(1).padStart(4, '0')}:00`;
284:     } else if (this.mode === 'sandbox') {
285:       this.objective = 'SANDBOX';
286:       this.subObjective = 'SPAWN, POSSESS, DESTROY';
287:     } else {
288:       this.objective = 'FREE ROAM';
289:       this.subObjective = `${this.city.destructionCount} STRUCTURES DESTROYED`;
290:     }
291:   }
292: 
293:   checkEnd(dt) {
294:     if (this.mode !== 'battle' || this.resultShown || this.spectate) return;
295:     if (!this.player) return;
296:     const enemies = this.monsters.filter(m => m.team !== this.player.team);
297:     const allies = this.monsters.filter(m => m.team === this.player.team);
298:     const enemiesAlive = enemies.some(m => !m.dead);
299:     const alliesAlive = allies.some(m => !m.dead);
300:     if (!enemiesAlive && enemies.length) {
301:       this.resultPending += dt;
302:       if (this.resultPending > 1.5) this.showResult(true);
303:     } else if (!alliesAlive) {
304:       this.resultPending += dt;
305:       if (this.resultPending > 1.5) this.showResult(false);
306:     }
307:   }
