309:   showResult(win) {
310:     if (this.resultShown) return;
311:     this.resultShown = true;
312:     this.paused = true;
313:     if (win) { this.audio.victory(); this.cameraRig.cinematic = 2; }
314:     else this.audio.defeat();
315:     const stats = {
316:       time: Math.max(1, Math.round(this.time - this.stats.startTime)),
317:       destroyed: this.city.destructionCount,
318:       damage: Math.round(this.stats.damageDealt),
319:       kills: this.stats.kills,
320:     };
321:     this.ui?.showResult?.(win, stats);
322:   }
