334:   melee(attacker, kind, stats) {
335:     const f = attacker.forward;
336:     const origin = attacker.root.position.clone().addScaledVector(f, attacker.radius * 0.5);
337:     const centerY = attacker.root.position.y + attacker.height * 0.52;
338:     const range = stats.range + attacker.radius * 0.45;
339:     let hits = 0;
340:     for (const m of this.monsters) {
341:       if (m === attacker || m.dead) continue;
342:       if (m.team === attacker.team && this.mode !== 'sandbox') continue;
343:       const to = m.root.position.clone().sub(attacker.root.position).setY(0);
344:       const d = to.length();
345:       if (d > range + m.radius) continue;
346:       to.normalize();
347:       const dot = to.dot(f);
348:       if (dot < Math.cos(Math.min(Math.PI, stats.arc) / 2)) continue;
349:       const point = m.root.position.clone().setY(centerY + (Math.random() - 0.5) * m.height * 0.2);
350:       const dmg = stats.damage * (1 - Math.max(0, d - attacker.radius) / (range * 2.2));
351:       const dealt = m.takeDamage(dmg, attacker, point, stats.force, 'impact');
352:       if (attacker === this.player) this.stats.damageDealt += dealt;
353:       this.effects.sparks(point, 10, 0xffd28a, 18);
354:       this.effects.blood(point, 4);
355:       hits++;
356:     }
357:     // city destruction in front
358:     const hitPoint = attacker.root.position.clone().addScaledVector(f, stats.range * 0.55).setY(Math.max(2, centerY * 0.7));
359:     const cityRadius = Math.max(attacker.radius, stats.range * 0.65);
360:     const before = this.city.destructionCount;
361:     this.city.damageAt(hitPoint, cityRadius, stats.damage * 0.9, { source: attacker });
362:     if (this.city.destructionCount > before) this.effects.shakeCamera(0.35, 0.5);
363:     this.effects.dust(hitPoint, attacker.radius * 0.5, 6, 0x9a8f80);
364:     return { hit: hits, point: hitPoint };
365:   }
366: 
367:   aoe(attacker, center, radius, damage, force, type = 'impact', opts = {}) {
368:     let hits = 0;
369:     for (const m of this.monsters) {
370:       if (m === attacker || m.dead) continue;
371:       if (m.team === attacker.team) continue;
372:       const d = m.root.position.distanceTo(center);
373:       if (d > radius + m.radius) continue;
374:       const fall = 1 - d / (radius + m.radius);
375:       const dir = m.root.position.clone().sub(center).setY(0).normalize();
376:       const status = type === 'firestorm' ? 'burn' : type === 'acid' ? 'acid' : type === 'freezeBeam' ? 'freeze' : 'impact';
377:       const dealt = m.takeDamage(damage * (0.45 + fall * 0.75), attacker, center.clone(), force * (0.5 + fall), status);
378:       if (attacker === this.player) this.stats.damageDealt += dealt;
379:       hits++;
380:     }
381:     if (opts.building !== false) {
382:       this.city.damageAt(center, radius, damage * 0.8, { source: attacker });
383:     }
384:     if (opts.color) this.effects.shockwave(center, radius, opts.color);
385:     this.effects.shakeCamera(0.3 + radius / 100, 0.5);
386:     return hits;
387:   }
