389:   roarWave(monster) {
390:     const center = monster.root.position;
391:     this.effects.shockwave(center, monster.height * 0.9, monster.def.colors.glow);
392:     this.effects.dust(center.clone(), monster.radius * 1.2, 24, 0x9a8f80);
393:     this.effects.shakeCamera(0.3, 0.7);
394:     this.cameraRig.cinematic = Math.max(this.cameraRig.cinematic, 0.5);
395:     for (const m of this.monsters) {
396:       if (m === monster || m.dead) continue;
397:       const d = m.root.position.distanceTo(center);
398:       if (d < monster.height * 2.6) {
399:         if (m.team === monster.team) {
400:           m.stamina = Math.min(m.maxStamina, m.stamina + 18);
401:         } else {
402:           m.balance -= 12;
403:           const dir = m.root.position.clone().sub(center).setY(0).normalize();
404:           m.velocity.addScaledVector(dir, 5);
405:           if (m.balance <= 0) m.knockdown(dir, 6);
406:         }
407:       }
408:     }
409:     for (const ped of this.city.pedestrians) {
410:       if (ped.group.position.distanceTo(center) < 220) ped.panic = 1;
411:     }
412:   }
