414:   findGrabTarget(monster) {
415:     const f = monster.forward;
416:     let best = null, bd = 1e9;
417:     for (const m of this.monsters) {
418:       if (m === monster || m.dead) continue;
419:       if (m.team === monster.team) continue;
420:       const to = m.root.position.clone().sub(monster.root.position).setY(0);
421:       const d = to.length();
422:       if (d > monster.radius + m.radius + monster.height * 0.22) continue;
423:       to.normalize();
424:       if (to.dot(f) < 0.15) continue;
425:       if (d < bd) { bd = d; best = m; }
426:     }
427:     return best;
428:   }
