430:   beamTarget(monster, origin, dir, range) {
431:     const ray = new THREE.Ray(origin, dir.clone().normalize());
432:     let best = { point: origin.clone().addScaledVector(dir, range), distance: range, monster: null, building: null };
433:     for (const m of this.monsters) {
434:       if (m === monster || m.dead) continue;
435:       if (m.team === monster.team) continue;
436:       const center = m.root.position.clone().add(new THREE.Vector3(0, m.height * 0.55, 0));
437:       const sphere = new THREE.Sphere(center, m.height * 0.32);
438:       const hit = ray.intersectSphere(sphere, new THREE.Vector3());
439:       if (hit) {
440:         const d = hit.distanceTo(origin);
441:         if (d < best.distance) best = { point: hit, distance: d, monster: m, building: null };
442:       }
443:     }
444:     const b = this.city.raycastBuilding(origin, dir, Math.min(range, best.distance));
445:     if (b) best = { point: b.point, distance: b.distance, monster: null, building: b.building };
446:     if (dir.y < -0.02) {
447:       const t = -origin.y / dir.y;
448:       if (t > 0 && t < best.distance) {
449:         best = { point: origin.clone().addScaledVector(dir, t).setY(0.6), distance: t, monster: null, building: null };
450:       }
451:     }
452:     return best;
453:   }
