455:   spawnBeam(monster, origin, dir, sp, width, duration, offset = 0) {
456:     const start = origin.clone();
457:     if (offset) start.add(new THREE.Vector3((Math.random() - 0.5) * offset, (Math.random() - 0.5) * offset, (Math.random() - 0.5) * offset));
458:     const res = this.beamTarget(monster, start, dir, sp.range);
459:     const effect = this.effects.beam({ start, end: res.point, color: sp.color, secondary: sp.secondary, width, duration });
460:     return { start, effect, target: res, dead: false };
461:   }
