26: class MonsterAI {
27:   constructor(monster) {
28:     this.m = monster;
29:     this.think = 0;
30:     this.target = null;
31:     this.blockTimer = 0;
32:     this.strafe = Math.random() > 0.5 ? 1 : -1;
33:     this.strafeTimer = 0;
34:     this.rampage = false;
35:     this.attackCooldown = 0;
36:     this.specialWish = 0;
37:   }
38: 
39:   update(dt) {
40:     const m = this.m;
41:     if (m.dead || m.state.grabbed) return;
42:     this.think -= dt;
43:     this.attackCooldown -= dt;
44:     this.blockTimer -= dt;
45:     this.strafeTimer -= dt;
46:     if (this.strafeTimer <= 0) { this.strafeTimer = 1.5 + Math.random() * 2.5; this.strafe *= -1; }
47:     if (this.think > 0) return;
48:     this.think = 0.18 + Math.random() * 0.18;
49: 
50:     const enemies = m.game.monsters.filter(o => o !== m && !o.dead && o.team !== m.team);
51:     let target = null, best = 1e9;
52:     for (const e of enemies) {
53:       const d = m.root.position.distanceTo(e.root.position);
54:       if (d < best) { best = d; target = e; }
55:     }
56:     if (!target && m.game.mode === 'battle' && m.game.player && m.game.player.team !== m.team && !m.game.player.dead) {
57:       target = m.game.player; best = m.root.position.distanceTo(target.root.position);
58:     }
59:     this.target = target;
60:     m.target = target;
61:     const intent = m.intent;
62:     intent.moveX = 0; intent.moveZ = 0; intent.run = false; intent.block = false;
63:     intent.attack = null; intent.special = false; intent.dodge = false; intent.jump = false; intent.grab = false; intent.roar = false;
64: 
65:     if (m.state.ragdoll) return;
66: 
67:     if (!target) {
68:       // rampage: hunt the nearest standing building
69:       const buildings = m.game.city.buildings.filter(b => !b.destroyed);
70:       if (!buildings.length) return;
71:       let b = null, bd = 1e9;
72:       for (const cand of buildings) {
73:         const d = Math.hypot(cand.x - m.root.position.x, cand.z - m.root.position.z);
74:         if (d < bd) { bd = d; b = cand; }
75:       }
76:       if (!b) return;
77:       const dx = b.x - m.root.position.x, dz = b.z - m.root.position.z;
78:       const dist = Math.hypot(dx, dz);
79:       if (dist > Math.max(b.width, b.depth) * 0.7 + m.radius + 8) {
80:         intent.moveX = dx / (dist || 1); intent.moveZ = dz / (dist || 1); intent.run = dist > 90;
81:       } else {
82:         intent.aimYaw = Math.atan2(-dx, -dz);
83:         if (this.attackCooldown <= 0) {
84:           intent.attack = Math.random() > 0.55 ? 'heavy' : 'light';
85:           this.attackCooldown = 0.9 + Math.random() * 0.8;
86:         }
87:       }
88:       return;
89:     }
90: 
91:     const dx = target.root.position.x - m.root.position.x;
92:     const dz = target.root.position.z - m.root.position.z;
93:     const dist = Math.hypot(dx, dz);
94:     const range = m.attackDefs.light.range + m.radius * 0.5;
95:     const heavyRange = m.attackDefs.heavy.range + m.radius * 0.4;
96:     intent.aimYaw = Math.atan2(-dx, -dz);
97:     intent.faceTarget = target;
98: 
99:     // react to incoming attacks
100:     if (target.state.attack && dist < range * 1.7) {
101:       const kind = target.state.attack.kind;
102:       if (kind === 'heavy' && Math.random() < 0.3) intent.dodge = true;
103:       else if (Math.random() < 0.26) { intent.block = true; this.blockTimer = 0.5; }
104:     }
105:     if (this.blockTimer > 0) intent.block = true;
106: 
107:     if (m.hp < m.maxHp * 0.28 && Math.random() < 0.15) intent.roar = true;
108: 
109:     const special = m.def.special;
110:     const specialRange = special.type === 'beam' || special.type === 'tripleBeam' || special.type === 'freezeBeam' || special.type === 'godrays' ? special.range * 0.7 : special.range;
111:     if (m.cooldowns.special <= 0 && m.stamina > 28 && dist < specialRange && Math.random() < 0.5) {
112:       intent.special = true;
113:     }
114: 
115:     if (dist > range * 1.05) {
116:       let mx = dx / (dist || 1), mz = dz / (dist || 1);
117:       // slight strafe / flank
118:       if (dist < range * 2.6 && Math.random() < 0.35) {
119:         mx += -dz / (dist || 1) * 0.35 * this.strafe;
120:         mz += dx / (dist || 1) * 0.35 * this.strafe;
121:       }
122:       const len = Math.hypot(mx, mz) || 1;
123:       intent.moveX = mx / len; intent.moveZ = mz / len;
124:       intent.run = dist > range * 2.4;
125:       // if stuck against a building, swing at it
126:       if (m.blockedTimer > 0.45 && this.attackCooldown <= 0) {
127:         intent.attack = 'heavy';
128:         this.attackCooldown = 1.1;
129:       }
130:       if (dist < heavyRange && this.attackCooldown <= 0 && Math.random() < 0.35) {
131:         intent.attack = 'heavy';
132:         this.attackCooldown = 1.2 + Math.random() * 0.6;
133:       }
134:     } else {
135:       if (this.attackCooldown <= 0 && !m.state.attack && !m.state.ragdoll) {
136:         const r = Math.random();
137:         if (r < 0.55) intent.attack = 'light';
138:         else if (r < 0.78) intent.attack = 'heavy';
139:         else if (r < 0.88) intent.attack = 'bite';
140:         else if (r < 0.95) intent.attack = 'tail';
141:         else intent.grab = true;
142:         this.attackCooldown = 0.7 + Math.random() * 0.9;
143:       }
144:       // keep a little distance while attacking
145:       if (dist < range * 0.45 && Math.random() < 0.4) {
146:         intent.moveX = -dx / (dist || 1) * 0.4;
147:         intent.moveZ = -dz / (dist || 1) * 0.4;
148:       }
149:     }
150:     if (target.state.ragdoll && dist < heavyRange && this.attackCooldown <= 0) {
151:       intent.attack = 'heavy';
152:       this.attackCooldown = 1.4;
153:     }
154:     if (target.state.attack?.kind === 'special' && Math.random() < 0.2) intent.dodge = true;
155:     if (m.hp < m.maxHp * 0.35 && Math.random() < 0.25) intent.dodge = true;
156:   }
157: }
