301:     }
302:     if (intent.dodge && this.cooldowns.dodge <= 0 && this.stamina > 12 && this.canAct()) {
303:       this.startDodge(intent);
304:     }
305:     if (intent.jump && this.cooldowns.jump <= 0 && this.canAct()) {
306:       this.startJump();
307:     }
308:     if (intent.attack && this.canAct() && !this.state.attack) {
309:       this.startAttack(intent.attack, intent.aimYaw);
310:       this.intent.attack = null;
311:     }
312:     if (intent.special && this.canAct() && !this.state.attack && this.cooldowns.special <= 0 && this.stamina > 24) {
313:       this.startSpecial(intent.aimYaw);
314:       this.intent.special = false;
315:     }
316:     if (intent.grab && this.canAct() && !this.state.attack && this.cooldowns.grab <= 0 && this.stamina > 12) {
317:       this.startAttack('grab', intent.aimYaw);
318:       this.intent.grab = false;
319:     }
320:     if (intent.roar && this.canAct() && !this.state.attack && this.cooldowns.roar <= 0) {
321:       this.startAttack('roar', intent.aimYaw);
322:       this.intent.roar = false;
323:     }
