371:     this.root.position.z += this.velocity.z * dt;
372:     this.state.speed = Math.hypot(this.velocity.x, this.velocity.z);
373:     this.state.running = intent.run && this.state.speed > this.def.speed * 0.7;
374:     if (this.state.speed > 0.3) this.state.walkPhase += dt * (this.state.running ? 2.1 : 1.15) * (0.7 + this.state.speed / 60);
375:     this.resolveCollisions(dt, false);
376:     this.root.rotation.y = this.yaw;
377:     // footstep FX
378:     this.stepTimer -= dt * (0.4 + this.state.speed / 30);
379:     if (this.stepTimer <= 0 && this.state.speed > 1) {
380:       this.stepTimer = this.state.running ? 0.28 : 0.5;
381:       this.footstep();
382:     }
383:     // clamp world
384:     this.root.position.x = clamp(this.root.position.x, -420, 420);
385:     this.root.position.z = clamp(this.root.position.z, -420, 420);
386:   }
387: 
388:   footstep() {
389:     const f = this.forward;
390:     const p = this.root.position.clone().add(new THREE.Vector3(f.z * this.radius * 0.5, 0.5, -f.x * this.radius * 0.5));
391:     this.game.effects.dust(p, this.radius * 0.4, 4, 0xa89a86);
392:     if (this.isPlayer || this.game.camera.position.distanceTo(p) < 220) {
393:       this.audioStepTimer -= 1;
394:       if (this.audioStepTimer <= 0) {
395:         this.game.audio.stomp(0.55);
396:         this.audioStepTimer = 2;
397:         this.game.effects.shakeCamera(0.08, 0.2);
398:       }
399:     }
400:   }
401: 
402:   resolveCollisions(dt, dodging) {
403:     const hit = this.game.city.collideCircle(this.root.position.x, this.root.position.z, this.radius);
404:     if (hit.pushX || hit.pushZ) {
405:       this.root.position.x += hit.pushX;
406:       this.root.position.z += hit.pushZ;
407:       this.blockedTimer = 0.5;
408:       const speed = Math.hypot(this.velocity.x, this.velocity.z);
409:       if (speed > 8 && hit.hit) {
410:         const dmg = (speed * this.mass) / 250000 * (dodging ? 0.4 : 1);
411:         hit.hit.damage(dmg, this.root.position.clone().setY(this.height * 0.5), { source: this });
412:         this.velocity.multiplyScalar(0.55);
413:         this.game.effects.dust(this.root.position.clone().setY(this.height * 0.3), this.radius, 8, 0x9a8f80);
414:         this.game.audio.impact(0.6);
415:       }
416:     }
417:   }
418: 
419:   startAttack(kind, aimYaw = null) {
420:     if (!this.canAct()) return;
421:     if (kind === 'grab' && this.grabTarget) {
422:       this.throwGrabbed();
423:       return;
424:     }
425:     const stats = this.attackDefs[kind] || this.attackDefs.light;
426:     if (this.stamina < stats.stamina) {
427:       if (this.isPlayer) this.game.hud?.toast('NOT ENOUGH STAMINA', 'warn');
428:       return;
429:     }
430:     if (kind === 'grab' && this.cooldowns.grab > 0) return;
431:     if (aimYaw !== null && aimYaw !== undefined) this.yaw = aimYaw;
432:     this.stamina -= stats.stamina;
433:     this.state.attack = {
434:       kind, t: 0, dur: stats.dur, hit: stats.hit, hitDone: false,
435:       alt: this.combo % 2 === 1, stats, aimYaw,
436:     };
437:     this.combo++;
438:     if (kind === 'roar') {
439:       this.cooldowns.roar = stats.cd;
440:       this.game.audio.roar(this.def);
441:       this.game.roarWave?.(this);
442:     }
443:     if (kind === 'grab') this.cooldowns.grab = stats.cd;
444:     if (this.isPlayer) this.game.hud?.onAction(kind);
445:   }
446: 
447:   startSpecial(aimYaw = null) {
448:     if (!this.canAct() || this.cooldowns.special > 0) return;
449:     const sp = this.def.special;
450:     if (aimYaw !== null && aimYaw !== undefined) this.yaw = aimYaw;
451:     this.stamina -= 24;
452:     this.cooldowns.special = sp.cooldown;
453:     this.state.attack = {
454:       kind: 'special', t: 0, dur: sp.type === 'beam' || sp.type === 'tripleBeam' || sp.type === 'freezeBeam' || sp.type === 'godrays' ? 1.8 : 1.15,
455:       hit: 0.42, hitDone: false, special: sp, stats: { damage: sp.damage, range: sp.range, force: 20 }, aimYaw,
456:     };
457:     this.game.audio.roar(this.def);
458:     this.game.hud?.onAction('special');
459:     if (this.isPlayer) this.game.hud?.setSpecialName(sp.name);
460:   }
461: 
462:   startDodge(intent) {
463:     this.stamina -= 12;
