import * as THREE from 'three';
import '@fontsource/barlow-condensed/400.css';
import '@fontsource/barlow-condensed/500.css';
import '@fontsource/barlow-condensed/600.css';
import '@fontsource/barlow-condensed/700.css';
import '@fontsource/inter/400.css';
import '@fontsource/inter/500.css';
import '@fontsource/inter/600.css';
import '@fontsource/inter/700.css';
import './styles.css';
import { Settings } from './core/settings.js';
import { AudioEngine } from './core/audio.js';
import { Game } from './game/game.js';
import { MonsterData } from './monsters/data.js';
import { UI } from './ui/ui.js';

const canvas = document.getElementById('game');
const settings = new Settings();
const audio = new AudioEngine(settings);

const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: settings.get('quality') !== 'low',
  powerPreference: 'high-performance',
  stencil: false,
});
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1;
renderer.shadowMap.enabled = settings.get('shadows');
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.setPixelRatio(settings.pixelRatio);
renderer.setSize(window.innerWidth, window.innerHeight, false);

const ui = new UI({ settings, audio });

let game;
let attract = true;
let attractTime = 0;

function startAttract() {
  const ids = MonsterData.map((m) => m.id);
  const pick = () => ids[Math.floor(Math.random() * ids.length)];
  const playerId = pick();
  let enemyId = pick();
  while (enemyId === playerId) enemyId = pick();
  const weather = ['storm', 'rain', 'clear'][Math.floor(Math.random() * 3)];
  attract = true;
  attractTime = 0;
  game.start({
    mode: 'battle',
    playerId,
    enemies: [enemyId],
    allies: [],
    weather,
    time: Math.random() > 0.5 ? 'sunset' : 'night',
    intro: false,
    spectate: true,
    title: '',
  });
  game.paused = false;
  ui.showMenu();
}

game = new Game({
  renderer,
  settings,
  audio,
  ui,
  onExit: () => {
    startAttract();
  },
});
ui.setGame(game);
window.__game = game;
window.__settings = settings;

ui.onLaunch = (config) => {
  audio.unlock();
  audio.confirm();
  attract = false;
  game.start(config);
  ui.hideMenu();
};

ui.onQuit = () => {
  game.exitToMenu();
};

function applySettings(key) {
  renderer.setPixelRatio(settings.pixelRatio);
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  renderer.shadowMap.enabled = settings.get('shadows');
  game.environment.setShadows(settings.get('shadows'));
  game.effects.setQuality();
  audio.setSound(settings.get('sound'));
  audio.setMusic(settings.get('music'));
  if (key === 'hud') ui.applyHudVisibility();
  if (key === 'quality') ui.applySettingsView();
}

ui.onSettingsChange = (key) => applySettings(key);

window.addEventListener('resize', () => {
  const w = window.innerWidth;
  const h = window.innerHeight;
  renderer.setPixelRatio(settings.pixelRatio);
  renderer.setSize(w, h, false);
  game.camera.aspect = w / h;
  game.camera.updateProjectionMatrix();
});

function unlockAudio() {
  audio.unlock();
}
window.addEventListener('pointerdown', unlockAudio, { once: true });
window.addEventListener('keydown', unlockAudio, { once: true });

window.addEventListener('error', (event) => {
  console.error(event.error || event.message);
  ui.fatal(event.message || 'Unknown renderer error');
});
window.addEventListener('unhandledrejection', (event) => {
  console.error(event.reason);
  ui.fatal(event.reason?.message || String(event.reason));
});

startAttract();
ui.ready();

let last = performance.now();
let accumulator = 0;
let firstFrame = true;

function frame(now) {
  requestAnimationFrame(frame);
  const raw = Math.min(0.1, (now - last) / 1000);
  last = now;
  const limit = Number(settings.get('fpsLimit')) || 0;
  if (limit > 0) {
    accumulator += raw;
    if (accumulator < 1 / limit) return;
    const step = Math.min(accumulator, 0.05);
    accumulator = 0;
    tick(step);
  } else {
    tick(Math.min(raw, 0.05));
  }
  if (firstFrame) {
    firstFrame = false;
    ui.ready();
    document.body.classList.add('booted');
  }
}

function tick(dt) {
  if (attract && game.active) {
    attractTime += dt;
    const alive = game.monsters.some((m) => !m.dead);
    if (!alive || attractTime > 75) startAttract();
  }
  game.update(dt);
  renderer.render(game.scene, game.camera);
}

document.addEventListener('visibilitychange', () => {
  last = performance.now();
});

requestAnimationFrame(frame);

:root {
  --bg: #05070a;
  --bg-2: #080d12;
  --panel: rgba(9, 14, 19, 0.86);
  --panel-solid: #0a1016;
  --line: rgba(151, 180, 194, 0.16);
  --line-strong: rgba(190, 215, 225, 0.32);
  --text: #e9eff1;
  --muted: #8c9ba3;
  --faint: #5d6a72;
  --gold: #d7b46a;
  --gold-2: #f1d79a;
  --cyan: #5fd7ff;
  --red: #ff4655;
  --green: #7ce8a4;
  --titan: #d7b46a;
  --titan-soft: #8a7c5c;
  --font-display: 'Barlow Condensed', 'Arial Narrow', sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --cut: 14px;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-body);
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
}
body { user-select: none; -webkit-user-select: none; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; border: 0; background: none; }
button:disabled { cursor: default; opacity: .38; }
.hidden { display: none !important; }
kbd {
  font-family: var(--font-body);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .08em;
  padding: 3px 5px;
  border: 1px solid var(--line-strong);
  border-radius: 3px;
  color: var(--muted);
  background: rgba(255, 255, 255, .03);
}

#app { position: fixed; inset: 0; overflow: hidden; }
#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  touch-action: none;
}
#ui { position: absolute; inset: 0; pointer-events: none; z-index: 10; }
#ui > * { pointer-events: auto; }

/* ------------------------------- screen fx ------------------------------- */
.screen-fx { position: absolute; inset: 0; pointer-events: none; z-index: 5; }
.fx-vignette {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 50% 45%, transparent 38%, rgba(0, 0, 0, .32) 78%, rgba(0, 0, 0, .7) 100%);
}
.fx-grain {
  position: absolute; inset: -50%;
  opacity: .06;
  background-image:
    radial-gradient(circle at 20% 30%, #fff 0 .5px, transparent .6px),
    radial-gradient(circle at 70% 60%, #fff 0 .5px, transparent .6px),
    radial-gradient(circle at 45% 80%, #fff 0 .5px, transparent .6px);
  background-size: 3px 3px, 4px 4px, 5px 5px;
  animation: grain 1.1s steps(3) infinite;
}
@keyframes grain {
  0% { transform: translate(0, 0); }
  33% { transform: translate(-2%, 1%); }
  66% { transform: translate(1%, -2%); }
  100% { transform: translate(0, 0); }
}
.fx-scanline {
  position: absolute; inset: 0;
  opacity: .15;
  background: repeating-linear-gradient(to bottom, rgba(255, 255, 255, .035) 0 1px, transparent 1px 4px);
  mix-blend-mode: overlay;
}
#damage-flash {
  position: absolute; inset: 0; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(255, 40, 55, .5) 100%);
}
#damage-flash.active { animation: hitflash .22s ease-out; }
#damage-flash.blocked { background: radial-gradient(ellipse at center, transparent 45%, rgba(95, 215, 255, .45) 100%); }
@keyframes hitflash { 0% { opacity: .9; } 100% { opacity: 0; } }

/* -------------------------------- loading -------------------------------- */
.loading {
  position: fixed; inset: 0; z-index: 200;
  background: radial-gradient(ellipse at 50% 45%, #0c151d 0%, #05070a 62%, #020304 100%);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 12px; transition: opacity .7s ease;
}
.loading.done { opacity: 0; pointer-events: none; }
.loading.gone { display: none; }
.load-emblem { width: 132px; height: 132px; color: var(--gold); opacity: .9; filter: drop-shadow(0 0 24px rgba(215, 180, 106, .28)); }
.load-emblem svg { width: 100%; height: 100%; }
.load-title { font-family: var(--font-display); font-size: 52px; letter-spacing: .14em; line-height: 1; }
.load-title span { color: var(--gold); }
.load-bar { width: 240px; height: 2px; background: rgba(255, 255, 255, .1); overflow: hidden; margin-top: 8px; }
.load-bar i { display: block; width: 42%; height: 100%; background: var(--gold); animation: load 1.15s ease-in-out infinite; }
@keyframes load { 0% { transform: translateX(-110%); } 100% { transform: translateX(340%); } }
.load-copy { font-size: 9px; letter-spacing: .34em; color: var(--muted); }

/* -------------------------------- menu ----------------------------------- */
.screen { position: absolute; inset: 0; }
.menu {
  display: flex; flex-direction: column;
  background:
    linear-gradient(90deg, rgba(4, 7, 10, .95) 0%, rgba(4, 7, 10, .82) 34%, rgba(4, 7, 10, .28) 64%, rgba(4, 7, 10, .62) 100%),
    linear-gradient(0deg, rgba(4, 7, 10, .96) 0%, transparent 26%),
    linear-gradient(180deg, rgba(4, 7, 10, .7) 0%, transparent 18%);
  animation: menuIn .55s ease both;
}
@keyframes menuIn { from { opacity: 0; } to { opacity: 1; } }
.menu.hidden { display: none; }

.topbar {
  flex: 0 0 74px;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 4vw;
  border-bottom: 1px solid rgba(151, 180, 194, .1);
  backdrop-filter: blur(6px);
}
.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark { width: 38px; height: 38px; color: var(--gold); }
.brand-mark svg { width: 100%; height: 100%; }
.brand-copy { display: flex; flex-direction: column; line-height: 1; }
.brand-copy b { font-family: var(--font-display); font-size: 22px; letter-spacing: .18em; font-weight: 600; }
.brand-copy span { font-size: 7.5px; letter-spacing: .28em; color: var(--muted); margin-top: 4px; }
.topnav { display: flex; gap: 6px; }
.nav-btn {
  font-family: var(--font-display); font-size: 12px; letter-spacing: .2em;
  padding: 9px 13px; color: var(--muted); border: 1px solid transparent;
  transition: color .2s, border-color .2s, background .2s;
}
.nav-btn:hover { color: var(--text); border-color: var(--line); background: rgba(255, 255, 255, .03); }

.menu-scroll {
  flex: 1; overflow-y: auto; overflow-x: hidden;
  padding: 3.2vh 4vw 0;
  scrollbar-width: thin; scrollbar-color: rgba(215, 180, 106, .35) transparent;
}
.menu-scroll::-webkit-scrollbar { width: 5px; }
.menu-scroll::-webkit-scrollbar-thumb { background: rgba(215, 180, 106, .35); }
.menu-hero {
  display: grid; grid-template-columns: minmax(0, 1.22fr) minmax(320px, .78fr);
  gap: clamp(22px, 4vw, 64px); align-items: center;
  max-width: 1580px; margin: 0 auto;
}
.hero-copy { padding: 1vh 0 2vh; min-width: 0; }
.eyebrow {
  display: flex; align-items: center; gap: 9px;
  font-size: 9px; font-weight: 600; letter-spacing: .32em; color: var(--muted);
  margin-bottom: 10px;
}
.live-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--red); box-shadow: 0 0 10px var(--red); animation: blink 1.4s infinite; }
@keyframes blink { 50% { opacity: .25; } }
.hero-title {
  margin: 0; font-family: var(--font-display); font-weight: 700;
  font-size: clamp(72px, 10.5vw, 156px); line-height: .78; letter-spacing: -.005em;
  text-transform: uppercase; text-shadow: 0 18px 60px rgba(0, 0, 0, .7);
}
.hero-title span {
  display: inline-block; margin-left: .06em;
  background: linear-gradient(180deg, var(--gold-2) 0%, var(--gold) 42%, #8e6f33 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 0 24px rgba(215, 180, 106, .18));
}
.hero-sub { margin: 14px 0 22px; font-size: 14px; color: #b9c5ca; letter-spacing: .01em; max-width: 520px; }
.mode-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; max-width: 640px; }
.mode-card {
  position: relative; text-align: left; padding: 13px 12px 11px;
  background: linear-gradient(180deg, rgba(255, 255, 255, .035), rgba(255, 255, 255, .008));
  border: 1px solid var(--line); border-top-color: rgba(255, 255, 255, .1);
  transition: transform .2s, border-color .2s, background .2s;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%);
}
.mode-card:hover { transform: translateY(-2px); border-color: var(--line-strong); background: rgba(255, 255, 255, .05); }
.mode-card.active {
  border-color: rgba(215, 180, 106, .72);
  background: linear-gradient(180deg, rgba(215, 180, 106, .16), rgba(215, 180, 106, .03));
  box-shadow: inset 0 0 24px rgba(215, 180, 106, .07);
}
.mode-card.active::before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 2px; background: var(--gold); }
.mode-num { display: block; font-size: 8px; letter-spacing: .2em; color: var(--gold); margin-bottom: 7px; }
.mode-card b { display: block; font-family: var(--font-display); font-size: 16px; letter-spacing: .1em; }
.mode-card > span:last-child { display: block; margin-top: 2px; font-size: 9.5px; color: var(--muted); }

.launch-row { display: flex; align-items: center; gap: 10px; margin: 18px 0 20px; }
.btn {
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 12px;
  min-height: 42px; padding: 0 22px;
  font-family: var(--font-display); font-size: 15px; font-weight: 600; letter-spacing: .16em;
  border: 1px solid var(--line-strong); color: var(--text);
  background: rgba(255, 255, 255, .025);
  transition: background .2s, border-color .2s, color .2s, transform .12s;
  clip-path: polygon(0 0, calc(100% - 9px) 0, 100% 9px, 100% 100%, 9px 100%, 0 calc(100% - 9px));
}
.btn:hover { background: rgba(255, 255, 255, .07); border-color: var(--line-strong); transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn-primary {
  color: #12100a; border-color: transparent;
  background: linear-gradient(100deg, #e8cf95 0%, var(--gold) 55%, #b08a3e 100%);
  box-shadow: 0 10px 30px rgba(215, 180, 106, .16);
}
.btn-primary:hover { background: linear-gradient(100deg, #f6e2b2 0%, #e2bf76 55%, #c39a49 100%); }
.btn-primary kbd { color: #4a3a17; border-color: rgba(30, 22, 6, .35); background: rgba(255, 255, 255, .2); }
.btn-ghost { color: #c3cdd1; }
.btn-small { min-height: 32px; padding: 0 13px; font-size: 11px; }
.btn.danger { color: #ff9aa2; border-color: rgba(255, 70, 85, .35); }
.btn.danger:hover { background: rgba(255, 70, 85, .12); }

.hero-stats { display: flex; gap: clamp(18px, 3vw, 44px); }
.hero-stats div { display: flex; flex-direction: column; gap: 2px; }
.hero-stats b { font-family: var(--font-display); font-size: 27px; font-weight: 500; color: var(--gold-2); line-height: 1; }
.hero-stats span { font-size: 7.5px; letter-spacing: .22em; color: var(--muted); }
.launch-summary {
  margin-top: 15px; font-size: 9px; letter-spacing: .22em; color: var(--faint);
  border-left: 1px solid rgba(215, 180, 106, .4); padding-left: 10px;
}

/* dossier */
.dossier {
  --titan: #d7b46a;
  position: relative; align-self: center;
  background: linear-gradient(160deg, rgba(13, 20, 27, .92), rgba(6, 10, 14, .88));
  border: 1px solid rgba(151, 180, 194, .18);
  padding: 16px 17px 15px;
  clip-path: polygon(0 0, calc(100% - 20px) 0, 100% 20px, 100% 100%, 20px 100%, 0 calc(100% - 20px));
  box-shadow: 0 30px 90px rgba(0, 0, 0, .55), inset 0 1px 0 rgba(255, 255, 255, .05);
  backdrop-filter: blur(14px);
  max-width: 430px; width: 100%; justify-self: end;
}
.dossier::before {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(circle at 50% 18%, color-mix(in srgb, var(--titan) 13%, transparent), transparent 56%);
}
.dossier-head { display: flex; justify-content: space-between; font-size: 8px; letter-spacing: .24em; color: var(--muted); position: relative; }
.portrait-wrap { position: relative; height: 178px; display: grid; place-items: center; margin: 6px 0 2px; }
.portrait { width: 148px; height: 148px; position: relative; z-index: 2; color: var(--titan); filter: drop-shadow(0 0 22px color-mix(in srgb, var(--titan) 32%, transparent)); }
.portrait svg { width: 100%; height: 100%; }
.portrait-glow { position: absolute; inset: 8%; border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, var(--titan) 22%, transparent), transparent 68%); filter: blur(6px); }
.portrait-rings { position: absolute; width: 168px; height: 168px; border: 1px solid rgba(151, 180, 194, .12); border-radius: 50%; }
.portrait-rings::before, .portrait-rings::after {
  content: ''; position: absolute; inset: 12px; border-radius: 50%;
  border: 1px dashed rgba(151, 180, 194, .16); animation: spin 24s linear infinite;
}
.portrait-rings::after { inset: -12px; border-style: solid; border-color: color-mix(in srgb, var(--titan) 16%, transparent); animation-direction: reverse; animation-duration: 32s; }
@keyframes spin { to { transform: rotate(360deg); } }
.portrait-scan {
  position: absolute; left: 8%; right: 8%; height: 1px;
  background: linear-gradient(90deg, transparent, var(--titan), transparent);
  opacity: .5; animation: scan 3.2s ease-in-out infinite;
}
@keyframes scan { 0%, 100% { top: 18%; } 50% { top: 82%; } }
.dossier-title { display: flex; justify-content: space-between; align-items: flex-end; gap: 10px; position: relative; }
.dossier-title > div > span { font-size: 8px; letter-spacing: .24em; color: var(--titan); }
.dossier-title h2 { margin: 2px 0 0; font-family: var(--font-display); font-size: 30px; line-height: 1; letter-spacing: .02em; text-transform: uppercase; }
.family-tag { font-size: 7.5px; letter-spacing: .2em; color: var(--muted); border: 1px solid var(--line); padding: 4px 6px; white-space: nowrap; }
.tagline { margin: 7px 0 10px; font-size: 10.5px; line-height: 1.45; color: #aab8bd; font-style: italic; position: relative; }
.stat-list { display: grid; gap: 5px; position: relative; }
.stat-row { display: grid; grid-template-columns: 52px 1fr 24px; align-items: center; gap: 8px; }
.stat-row span { font-size: 7.5px; letter-spacing: .18em; color: var(--muted); }
.stat-row b { font-size: 9px; font-weight: 600; text-align: right; color: #c9d3d7; }
.stat-track { height: 3px; background: rgba(255, 255, 255, .08); overflow: hidden; }
.stat-track i { display: block; height: 100%; background: linear-gradient(90deg, color-mix(in srgb, var(--titan) 55%, #334), var(--titan)); }
.ability-list { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 10px; margin-top: 11px; padding-top: 10px; border-top: 1px solid var(--line); position: relative; }
.ability-list div { display: flex; flex-direction: column; gap: 1px; }
.ability-list span { font-size: 6.5px; letter-spacing: .2em; color: var(--faint); }
.ability-list b { font-family: var(--font-display); font-size: 12px; font-weight: 500; letter-spacing: .04em; }
.ability-list .special b { color: var(--gold-2); }
.rival-block { margin-top: 11px; padding-top: 9px; border-top: 1px solid var(--line); position: relative; }
.rival-head { display: flex; justify-content: space-between; font-size: 7px; letter-spacing: .18em; color: var(--faint); margin-bottom: 5px; }
.rival-head span:last-child { color: #b8c4c9; }
.rival-chips { display: flex; flex-wrap: wrap; gap: 4px; max-height: 62px; overflow-y: auto; scrollbar-width: thin; }
.rival-chips .chip { font-size: 8px; padding: 3px 6px; }
.chip em { font-style: normal; color: var(--faint); font-size: 7px; margin-left: 3px; }

/* config strip */
.config-strip {
  display: grid; grid-template-columns: 1.1fr 1fr 1fr; gap: 18px;
  max-width: 1580px; margin: 2.4vh auto 0;
  padding: 12px 0; border-top: 1px solid rgba(151, 180, 194, .12); border-bottom: 1px solid rgba(151, 180, 194, .12);
}
.config-block label { display: block; font-size: 7.5px; letter-spacing: .24em; color: var(--faint); margin-bottom: 7px; }
.chips { display: flex; flex-wrap: wrap; gap: 5px; }
.chip {
  font-family: var(--font-display); font-size: 11px; letter-spacing: .1em;
  padding: 5px 9px; color: var(--muted);
  border: 1px solid var(--line); background: rgba(255, 255, 255, .018);
  transition: all .18s;
}
.chip:hover { color: var(--text); border-color: var(--line-strong); background: rgba(255, 255, 255, .05); }
.chip.active { color: #161208; background: var(--gold); border-color: var(--gold); }
.chip.active em { color: rgba(20, 15, 4, .55); }
.chip.disabled, .chips.disabled { opacity: .3; pointer-events: none; }
.chips.compact .chip { padding: 4px 7px; font-size: 10px; }

/* roster */
.roster-wrap { max-width: 1580px; margin: 2vh auto 0; padding-bottom: 4vh; }
.section-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 9px; }
.section-head span:first-child { font-family: var(--font-display); font-size: 13px; letter-spacing: .24em; color: #c6d0d4; }
.section-head span:last-child { font-size: 7.5px; letter-spacing: .2em; color: var(--faint); }
.roster { display: grid; grid-template-columns: repeat(auto-fill, minmax(148px, 1fr)); gap: 6px; }
.titan-card {
  position: relative; display: flex; align-items: center; gap: 8px;
  min-height: 62px; padding: 7px 9px 7px 7px; text-align: left;
  border: 1px solid var(--line); background: linear-gradient(180deg, rgba(255, 255, 255, .025), rgba(255, 255, 255, .005));
  transition: border-color .18s, background .18s, transform .18s;
  overflow: hidden;
}
.titan-card::after { content: ''; position: absolute; left: 0; bottom: 0; height: 2px; width: 0; background: var(--titan); transition: width .25s; }
.titan-card:hover { border-color: var(--line-strong); transform: translateY(-2px); background: rgba(255, 255, 255, .045); }
.titan-card.active { border-color: color-mix(in srgb, var(--titan) 62%, transparent); background: linear-gradient(180deg, color-mix(in srgb, var(--titan) 12%, transparent), rgba(255, 255, 255, .01)); }
.titan-card.active::after { width: 100%; }
.titan-index { position: absolute; top: 4px; right: 6px; font-size: 7px; color: var(--faint); letter-spacing: .1em; }
.titan-glyph { flex: 0 0 34px; width: 34px; height: 34px; color: var(--titan); opacity: .85; }
.titan-glyph svg { width: 100%; height: 100%; }
.titan-card-copy { display: flex; flex-direction: column; min-width: 0; }
.titan-card-copy b { font-family: var(--font-display); font-size: 13px; letter-spacing: .06em; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.titan-card-copy small { font-size: 6.5px; letter-spacing: .13em; color: var(--muted); margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.titan-power { position: absolute; bottom: 4px; right: 6px; font-family: var(--font-display); font-size: 11px; color: color-mix(in srgb, var(--titan) 75%, #fff); }
.menu-foot {
  flex: 0 0 34px; display: flex; justify-content: space-between; align-items: center;
  padding: 0 4vw; font-size: 7px; letter-spacing: .22em; color: #4d5a61;
  border-top: 1px solid rgba(151, 180, 194, .08);
  background: rgba(3, 5, 7, .55);
}

/* --------------------------------- HUD ----------------------------------- */
.hud { position: absolute; inset: 0; pointer-events: none; }
.hud > * { pointer-events: auto; }
.hud.hidden { display: none; }
.hud-off .ability-bar, .hud-off .objective-card, .hud-off .minimap-wrap, .hud-off .hud-center { opacity: 0; pointer-events: none; }
.hud-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; padding: 16px 20px 0; }
.objective-card {
  min-width: 290px; max-width: 440px;
  background: linear-gradient(120deg, rgba(7, 12, 17, .9), rgba(7, 12, 17, .62));
  border: 1px solid var(--line); border-left: 2px solid var(--gold);
  padding: 9px 13px 8px; backdrop-filter: blur(9px);
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%);
}
.hud-mode { display: block; font-size: 7px; letter-spacing: .26em; color: var(--gold); margin-bottom: 3px; }
.objective-card b { display: block; font-family: var(--font-display); font-size: 17px; letter-spacing: .07em; line-height: 1.05; }
.objective-card small { display: block; font-size: 7px; letter-spacing: .15em; color: var(--muted); margin-top: 4px; }
.hud-center { position: absolute; left: 50%; top: 14px; transform: translateX(-50%); text-align: center; }
.clock { font-family: var(--font-display); font-size: 25px; letter-spacing: .12em; color: #e7edf0; text-shadow: 0 2px 10px #000; font-variant-numeric: tabular-nums; }
.mini-chips { display: flex; gap: 5px; justify-content: center; margin-top: 2px; }
.mini-chips span { font-size: 6.5px; letter-spacing: .16em; color: var(--muted); border: 1px solid var(--line); padding: 2px 5px; background: rgba(4, 8, 11, .5); }
.hud-tools { display: flex; gap: 5px; }
.icon-btn {
  width: 36px; height: 36px; display: grid; place-items: center;
  border: 1px solid var(--line); background: rgba(6, 11, 15, .78);
  color: #c7d2d6; font-family: var(--font-display); font-size: 14px; letter-spacing: .05em;
  backdrop-filter: blur(6px); transition: all .18s;
}
.icon-btn:hover { border-color: var(--gold); color: var(--gold); }

.hud-bottom {
  position: absolute; left: 18px; right: 18px; bottom: 16px;
  display: grid; grid-template-columns: minmax(250px, 330px) 1fr 178px;
  align-items: end; gap: 16px;
}
.player-card {
  background: linear-gradient(120deg, rgba(7, 12, 17, .92), rgba(7, 12, 17, .72));
  border: 1px solid var(--line); border-left: 2px solid var(--cyan);
  padding: 10px 12px 9px; backdrop-filter: blur(10px);
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 0 100%);
  transition: border-color .2s;
}
.player-card.low { border-left-color: var(--red); }
.player-card.dead { opacity: .6; }
.player-id { display: flex; align-items: baseline; gap: 8px; }
.player-team { font-size: 6.5px; letter-spacing: .2em; color: var(--cyan); }
.player-id b { font-family: var(--font-display); font-size: 19px; letter-spacing: .06em; font-weight: 600; line-height: 1; }
.player-hp-label { margin-left: auto; font-size: 8px; color: var(--muted); font-variant-numeric: tabular-nums; }
.bar { position: relative; height: 12px; margin-top: 6px; background: rgba(255, 255, 255, .09); overflow: hidden; }
.bar.hp { height: 13px; }
.bar i { display: block; width: 100%; height: 100%; transform-origin: left; background: linear-gradient(90deg, #3fa9d8, #6ce0ff); transition: transform .12s linear; }
.bar.hp i { background: linear-gradient(90deg, #2e93c4, #65dcff 60%, #b8f4ff); }
.player-card.low .bar.hp i { background: linear-gradient(90deg, #a81d2c, #ff4655 60%, #ff8a93); }
.bar.stamina { height: 5px; margin-top: 4px; }
.bar.stamina i { background: linear-gradient(90deg, #a37b32, #e7c477); }
.bar-ticks { position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 calc(10% - 1px), rgba(0, 0, 0, .4) calc(10% - 1px) 10%); }
.player-sub { display: flex; justify-content: space-between; align-items: center; margin-top: 6px; font-size: 7px; letter-spacing: .16em; color: var(--muted); }
.special-mini { display: flex; align-items: center; gap: 5px; }
.special-mini i { display: block; width: 46px; height: 3px; background: rgba(255, 255, 255, .1); position: relative; overflow: hidden; }
.special-mini i::after { content: ''; position: absolute; inset: 0; background: var(--gold); transform-origin: left; transform: scaleX(0); transition: transform .15s; }
.special-mini.ready i::after { transform: scaleX(1); box-shadow: 0 0 8px var(--gold); }
.special-mini em { font-style: normal; color: var(--gold-2); font-size: 7px; letter-spacing: .1em; }

.ability-bar { display: flex; justify-content: center; align-items: flex-end; gap: 5px; flex-wrap: wrap; }
.ability {
  width: 68px; height: 54px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px;
  border: 1px solid var(--line); background: linear-gradient(180deg, rgba(9, 14, 19, .82), rgba(5, 9, 12, .9));
  backdrop-filter: blur(6px); transition: all .16s; position: relative; overflow: hidden;
}
.ability::before { content: ''; position: absolute; inset: 0; background: radial-gradient(circle at 50% 120%, rgba(95, 215, 255, .18), transparent 65%); opacity: 0; transition: opacity .2s; }
.ability:hover { border-color: var(--line-strong); transform: translateY(-2px); }
.ability:hover::before { opacity: 1; }
.ability b { font-family: var(--font-display); font-size: 11px; letter-spacing: .1em; font-weight: 600; }
.ability kbd { background: none; border: 0; padding: 0; font-size: 7px; color: var(--faint); }
.ability.special { border-color: rgba(215, 180, 106, .45); background: linear-gradient(180deg, rgba(215, 180, 106, .14), rgba(8, 12, 16, .9)); }
.ability.special b { color: var(--gold-2); }
.ability.flash { animation: abilityFlash .26s ease-out; }
@keyframes abilityFlash {
  0% { background: rgba(215, 180, 106, .55); transform: translateY(-3px); }
  100% { background: rgba(255, 255, 255, .02); }
}

.minimap-wrap { position: relative; justify-self: end; width: 178px; }
.minimap-wrap canvas { width: 178px; height: 178px; display: block; border: 1px solid var(--line); background: rgba(4, 8, 11, .7); }
.minimap-wrap span { position: absolute; left: 7px; top: 5px; font-size: 6.5px; letter-spacing: .2em; color: var(--gold); }
.minimap-wrap em { position: absolute; right: 7px; bottom: 5px; font-style: normal; font-size: 6.5px; letter-spacing: .14em; color: var(--muted); }

/* sandbox */
.sandbox-panel {
  position: absolute; right: 20px; top: 62px; width: 306px;
  background: linear-gradient(160deg, rgba(8, 13, 18, .95), rgba(5, 9, 12, .92));
  border: 1px solid var(--line); backdrop-filter: blur(12px);
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 0 100%);
  max-height: calc(100vh - 300px); display: flex; flex-direction: column;
  box-shadow: 0 20px 60px rgba(0, 0, 0, .5);
}
.sandbox-head { display: flex; justify-content: space-between; align-items: center; padding: 9px 11px; border-bottom: 1px solid var(--line); font-size: 8px; letter-spacing: .22em; color: var(--gold); }
.mini-x { width: 22px; height: 22px; display: grid; place-items: center; border: 1px solid var(--line); color: var(--muted); font-size: 15px; line-height: 1; }
.mini-x:hover { color: var(--text); border-color: var(--line-strong); }
.sandbox-tabs { display: grid; grid-template-columns: 1fr 1fr; border-bottom: 1px solid var(--line); }
.sandbox-tabs button { padding: 7px; font-family: var(--font-display); font-size: 10px; letter-spacing: .16em; color: var(--muted); border-bottom: 2px solid transparent; }
.sandbox-tabs button.active { color: var(--gold-2); border-bottom-color: var(--gold); background: rgba(215, 180, 106, .06); }
.sandbox-body { overflow-y: auto; padding: 9px 10px 11px; scrollbar-width: thin; }
.sandbox-label { font-size: 6.5px; letter-spacing: .22em; color: var(--faint); margin: 7px 0 5px; }
.sandbox-label:first-child { margin-top: 0; }
.sandbox-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; }
.sandbox-grid > button {
  min-height: 32px; padding: 4px; border: 1px solid var(--line); background: rgba(255, 255, 255, .02);
  font-family: var(--font-display); font-size: 9px; letter-spacing: .06em; color: #c0cbcf; transition: all .15s;
}
.sandbox-grid > button:hover { border-color: var(--line-strong); background: rgba(255, 255, 255, .06); }
.sandbox-titan { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px; min-height: 48px !important; color: var(--titan) !important; }
.sandbox-titan svg { width: 24px; height: 24px; }
.sandbox-titan span { font-size: 6px; letter-spacing: .04em; color: #b8c3c7; }
.sandbox-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: 9px; }
.sandbox-note { font-size: 7px; letter-spacing: .14em; color: var(--faint); }

/* mobile controls */
.mobile-controls { display: none; position: absolute; inset: 0; pointer-events: none; }
.mobile-controls.visible { display: block; }
.joystick {
  position: absolute; left: 24px; bottom: 150px; width: 128px; height: 128px; border-radius: 50%;
  border: 1px solid rgba(151, 180, 194, .3); background: radial-gradient(circle, rgba(9, 14, 19, .6), rgba(9, 14, 19, .22));
  pointer-events: auto; touch-action: none; backdrop-filter: blur(4px);
}
.joystick::before { content: ''; position: absolute; inset: 22px; border-radius: 50%; border: 1px dashed rgba(151, 180, 194, .18); }
.joystick-knob { position: absolute; left: 50%; top: 50%; width: 50px; height: 50px; margin: -25px 0 0 -25px; border-radius: 50%; background: radial-gradient(circle at 40% 35%, rgba(215, 180, 106, .8), rgba(120, 92, 40, .55)); border: 1px solid rgba(241, 215, 154, .55); box-shadow: 0 0 20px rgba(215, 180, 106, .18); }
.mobile-actions { position: absolute; right: 16px; bottom: 26px; width: 230px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; pointer-events: none; }
.mob-btn {
  pointer-events: auto; height: 58px; border-radius: 50%;
  border: 1px solid rgba(151, 180, 194, .28); background: radial-gradient(circle at 40% 30%, rgba(20, 30, 38, .9), rgba(7, 11, 15, .82));
  font-family: var(--font-display); font-size: 10px; letter-spacing: .08em; color: #d3dde0;
  backdrop-filter: blur(4px); touch-action: none;
}
.mob-btn.attack { background: radial-gradient(circle at 40% 30%, rgba(215, 180, 106, .38), rgba(20, 16, 8, .9)); border-color: rgba(215, 180, 106, .55); color: var(--gold-2); }
.mob-btn.special { border-color: rgba(95, 215, 255, .45); color: #a9edff; }
.mob-btn.block, .mob-btn.run { height: 46px; align-self: end; font-size: 8px; }
.mob-btn.active { background: rgba(215, 180, 106, .35); }

/* ------------------------------- overlays -------------------------------- */
.overlay {
  position: fixed; inset: 0; z-index: 80;
  background: rgba(2, 4, 7, .68); backdrop-filter: blur(9px);
  display: grid; place-items: center; padding: 20px;
  animation: fadeIn .2s ease both;
}
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
.modal {
  width: min(92vw, 680px); max-height: 88vh; display: flex; flex-direction: column;
  background: linear-gradient(160deg, rgba(11, 17, 23, .98), rgba(5, 9, 12, .98));
  border: 1px solid var(--line-strong);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px));
  box-shadow: 0 40px 120px rgba(0, 0, 0, .7), inset 0 1px 0 rgba(255, 255, 255, .06);
  animation: modalIn .28s cubic-bezier(.2, .8, .2, 1) both;
}
@keyframes modalIn { from { opacity: 0; transform: translateY(16px) scale(.98); } to { opacity: 1; transform: none; } }
.modal.hidden { display: none; }
.modal-head { display: flex; justify-content: space-between; align-items: center; padding: 12px 16px; border-bottom: 1px solid var(--line); font-family: var(--font-display); font-size: 13px; letter-spacing: .22em; color: #cbd6da; }
.modal-foot { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 12px 16px; border-top: 1px solid var(--line); font-size: 7px; letter-spacing: .2em; color: var(--faint); }
.pause-title { font-family: var(--font-display); font-size: clamp(40px, 7vw, 70px); line-height: 1; text-align: center; padding: 18px 0 4px; letter-spacing: .02em; color: #e7edf0; }
.pause-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; padding: 14px 18px; }
.pause-grid .btn { min-height: 48px; }
.pause-hint { text-align: center; font-size: 7px; letter-spacing: .22em; color: var(--faint); padding: 0 0 14px; }
.settings-scroll { overflow-y: auto; padding: 8px 18px 16px; }
.setting-row { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 9px 0; border-bottom: 1px solid rgba(151, 180, 194, .08); }
.setting-row label { font-size: 8px; letter-spacing: .18em; color: var(--muted); display: flex; align-items: center; gap: 8px; }
.setting-row output { color: var(--gold-2); font-size: 8px; }
.seg { display: flex; border: 1px solid var(--line); }
.seg button { padding: 6px 9px; font-family: var(--font-display); font-size: 10px; letter-spacing: .1em; color: var(--muted); border-right: 1px solid var(--line); }
.seg button:last-child { border-right: 0; }
.seg button:hover { color: var(--text); background: rgba(255, 255, 255, .05); }
.seg button.active { background: var(--gold); color: #171208; }
select { background: #0c1319; border: 1px solid var(--line); padding: 6px 8px; font-size: 9px; letter-spacing: .1em; color: #cfdadd; outline: none; }
select:focus { border-color: var(--gold); }
input[type='range'] { -webkit-appearance: none; appearance: none; width: 210px; height: 3px; background: rgba(255, 255, 255, .12); outline: none; }
input[type='range']::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; background: var(--gold); border-radius: 50%; cursor: pointer; box-shadow: 0 0 10px rgba(215, 180, 106, .4); }
.toggle-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 16px; margin-top: 12px; }
.switch { display: flex; align-items: center; gap: 9px; padding: 7px 0; cursor: pointer; }
.switch input { display: none; }
.switch i { width: 28px; height: 15px; border: 1px solid var(--line-strong); background: rgba(255, 255, 255, .04); position: relative; transition: all .18s; flex: 0 0 auto; }
.switch i::after { content: ''; position: absolute; left: 2px; top: 2px; width: 9px; height: 9px; background: #7c8a90; transition: all .18s; }
.switch input:checked + i { border-color: var(--gold); background: rgba(215, 180, 106, .18); }
.switch input:checked + i::after { left: 15px; background: var(--gold); box-shadow: 0 0 8px rgba(215, 180, 106, .5); }
.switch span { font-size: 8px; letter-spacing: .16em; color: var(--muted); }

.controls-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; padding: 16px 20px; overflow-y: auto; }
.controls-grid h3 { font-family: var(--font-display); font-size: 13px; letter-spacing: .18em; color: var(--gold); margin: 0 0 9px; }
.controls-grid h3 + p { margin-top: 0; }
.controls-grid p { font-size: 10.5px; line-height: 1.55; color: #a8b5ba; }
.key-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 4px 0; border-bottom: 1px solid rgba(151, 180, 194, .07); font-size: 8px; letter-spacing: .14em; color: var(--muted); }
.key-row kbd { min-width: 68px; text-align: center; color: #d8e2e5; }

.about-body { display: grid; grid-template-columns: 160px 1fr; gap: 22px; padding: 20px; align-items: start; }
.about-mark { color: var(--gold); opacity: .8; }
.about-mark svg { width: 100%; height: auto; }
.about-body h2 { font-family: var(--font-display); font-size: 38px; margin: 0 0 6px; letter-spacing: .04em; }
.about-body p { font-size: 11px; line-height: 1.6; color: #a8b5ba; margin: 0 0 10px; }
.about-meta { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 14px; }
.about-meta span { font-size: 7px; letter-spacing: .16em; border: 1px solid var(--line); padding: 4px 6px; color: var(--muted); }

.result-modal { width: min(92vw, 560px); text-align: center; }
.result-kicker { font-family: var(--font-display); font-size: 15px; letter-spacing: .5em; color: var(--gold); padding: 24px 0 0; }
.result-kicker.lose { color: var(--red); }
.result-title { font-family: var(--font-display); font-size: clamp(38px, 7vw, 62px); line-height: .95; margin: 6px 20px 14px; letter-spacing: .02em; }
.result-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; margin: 0 20px 18px; border: 1px solid var(--line); background: var(--line); }
.result-stats div { background: #080d12; padding: 10px 4px; display: flex; flex-direction: column; gap: 3px; }
.result-stats span { font-size: 6.5px; letter-spacing: .18em; color: var(--faint); }
.result-stats b { font-family: var(--font-display); font-size: 24px; font-weight: 500; color: var(--gold-2); }
.result-actions { display: flex; justify-content: center; flex-wrap: wrap; gap: 8px; padding: 0 20px 22px; }

.fatal-modal { width: min(92vw, 520px); }

/* toasts */
.toasts { position: fixed; right: 20px; top: 86px; z-index: 90; display: flex; flex-direction: column; gap: 6px; pointer-events: none; width: min(320px, 70vw); }
.toast {
  display: flex; align-items: center; gap: 9px; padding: 8px 11px;
  background: linear-gradient(90deg, rgba(8, 13, 18, .96), rgba(8, 13, 18, .78));
  border: 1px solid var(--line); border-left: 2px solid var(--cyan);
  transform: translateX(24px); opacity: 0; transition: all .25s ease;
  backdrop-filter: blur(8px);
}
.toast.show { transform: none; opacity: 1; }
.toast b { font-family: var(--font-display); font-size: 11px; letter-spacing: .12em; font-weight: 500; }
.toast-mark { width: 5px; height: 5px; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); flex: 0 0 auto; }
.toast.warn { border-left-color: var(--gold); }
.toast.warn .toast-mark { background: var(--gold); box-shadow: 0 0 8px var(--gold); }
.toast.kill { border-left-color: var(--red); }
.toast.kill .toast-mark { background: var(--red); box-shadow: 0 0 8px var(--red); }
.toast.info { border-left-color: var(--cyan); }

/* versus */
.versus {
  position: fixed; inset: 0; z-index: 70; display: flex; align-items: center; justify-content: center;
  gap: clamp(16px, 6vw, 90px); pointer-events: none;
  background: radial-gradient(ellipse at center, rgba(2, 4, 7, .2), rgba(2, 4, 7, .75));
  animation: versusIn .3s ease both;
}
.versus.hidden { display: none; }
@keyframes versusIn { from { opacity: 0; } to { opacity: 1; } }
.versus-side { display: flex; flex-direction: column; align-items: center; gap: 4px; width: 250px; }
.versus-side.enemy { text-align: right; }
.vs-glyph { width: clamp(110px, 16vw, 190px); height: clamp(110px, 16vw, 190px); filter: drop-shadow(0 0 30px currentColor); opacity: .9; }
.vs-glyph svg { width: 100%; height: 100%; }
.versus-side > span { font-size: 7px; letter-spacing: .34em; color: var(--muted); }
.versus-side > b { font-family: var(--font-display); font-size: clamp(22px, 3.4vw, 40px); letter-spacing: .06em; line-height: 1; }
.versus-side > em { font-style: normal; font-size: 7px; letter-spacing: .2em; color: var(--faint); }
.vs-mark { font-family: var(--font-display); font-size: clamp(34px, 6vw, 72px); color: var(--gold); text-shadow: 0 0 30px rgba(215, 180, 106, .5); position: relative; }
.vs-mark::before, .vs-mark::after { content: ''; position: absolute; top: 50%; width: 46px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold)); }
.vs-mark::before { right: 100%; margin-right: 12px; }
.vs-mark::after { left: 100%; margin-left: 12px; transform: rotate(180deg); }

.title-splash {
  position: fixed; left: 50%; top: 16%; transform: translateX(-50%);
  z-index: 65; font-family: var(--font-display); font-size: clamp(30px, 5vw, 62px);
  letter-spacing: .1em; text-align: center; white-space: nowrap; color: #eef3f5;
  text-shadow: 0 4px 30px rgba(0, 0, 0, .8); pointer-events: none; opacity: 0;
}
.title-splash.show { animation: titleIn 2.6s ease both; }
@keyframes titleIn {
  0% { opacity: 0; letter-spacing: .3em; }
  15% { opacity: 1; letter-spacing: .1em; }
  78% { opacity: 1; }
  100% { opacity: 0; letter-spacing: .06em; }
}
.action-flash { position: fixed; inset: 0; pointer-events: none; z-index: 4; }
.cinematic-bars { position: fixed; inset: 0; pointer-events: none; z-index: 40; }
.cinematic-bars i { position: absolute; left: 0; right: 0; height: 0; background: #000; transition: height .35s ease; }
.cinematic-bars i:first-child { top: 0; }
.cinematic-bars i:last-child { bottom: 0; }
.cinematic-bars.active i { height: 7vh; }

/* ------------------------------- responsive ------------------------------ */
@media (max-width: 1180px) {
  .menu-hero { grid-template-columns: 1fr; gap: 18px; }
  .dossier { justify-self: stretch; max-width: none; display: grid; grid-template-columns: 150px 1fr; column-gap: 18px; }
  .dossier-head { grid-column: 1 / -1; }
  .portrait-wrap { grid-row: span 3; height: 160px; margin: 0; }
  .dossier-title, .tagline, .stat-list, .ability-list, .rival-block { grid-column: 2; }
  .portrait-rings { width: 145px; height: 145px; }
  .ability-list { margin-top: 8px; }
  .config-strip { grid-template-columns: 1fr 1fr; }
  .hud-bottom { grid-template-columns: minmax(230px, 300px) 1fr; }
  .minimap-wrap { display: none; }
}
@media (max-width: 760px) {
  .topbar { flex-basis: 58px; padding: 0 16px; }
  .brand-mark { width: 28px; height: 28px; }
  .brand-copy b { font-size: 17px; }
  .brand-copy span { display: none; }
  .nav-btn { padding: 7px 7px; font-size: 10px; letter-spacing: .1em; }
  .menu-scroll { padding: 16px 16px 0; }
  .hero-title { font-size: clamp(58px, 17vw, 92px); }
  .hero-sub { font-size: 12px; margin: 10px 0 15px; }
  .mode-grid { grid-template-columns: 1fr; gap: 5px; }
  .mode-card { display: flex; align-items: baseline; gap: 10px; padding: 9px 10px; }
  .mode-num { margin: 0; }
  .mode-card > span:last-child { margin-left: auto; }
  .launch-row { flex-wrap: wrap; margin: 13px 0 15px; }
  .launch-row .btn { flex: 1; min-width: 130px; }
  .hero-stats { gap: 22px; }
  .dossier { display: block; padding: 12px; }
  .portrait-wrap { height: 128px; }
  .portrait { width: 110px; height: 110px; }
  .portrait-rings { width: 128px; height: 128px; }
  .dossier-title h2 { font-size: 24px; }
  .config-strip { grid-template-columns: 1fr; gap: 10px; padding: 10px 0; }
  .roster { grid-template-columns: 1fr 1fr; }
  .titan-card { min-height: 56px; }
  .menu-foot { display: none; }
  .hud-top { padding: 10px 12px 0; }
  .objective-card { min-width: 0; max-width: 58vw; padding: 7px 9px; }
  .objective-card b { font-size: 13px; }
  .objective-card small { font-size: 6px; }
  .hud-center { display: none; }
  .hud-bottom { left: 10px; right: 10px; bottom: 10px; grid-template-columns: 1fr; gap: 8px; }
  .player-card { padding: 8px 10px; }
  .ability-bar { display: none; }
  .minimap-wrap { display: none; }
  .sandbox-panel { top: 54px; right: 10px; width: min(92vw, 320px); max-height: calc(100vh - 220px); }
  .pause-grid { grid-template-columns: 1fr; }
  .pause-grid .btn { min-height: 40px; }
  .controls-grid { grid-template-columns: 1fr; gap: 16px; }
  .about-body { grid-template-columns: 1fr; }
  .about-mark { width: 90px; }
  .toggle-grid { grid-template-columns: 1fr; }
  .setting-row { flex-wrap: wrap; }
  input[type='range'] { width: 100%; }
  .result-stats { grid-template-columns: 1fr 1fr; }
  .versus { gap: 10px; }
  .versus-side { width: 40vw; }
  .vs-mark::before, .vs-mark::after { display: none; }
  .toasts { right: 10px; top: 62px; width: 62vw; }
}
@media (pointer: coarse) {
  .ability-bar { display: none; }
  .mobile-controls { display: block; }
  .hud-bottom { grid-template-columns: 1fr; }
  .minimap-wrap { display: none; }
  .player-card { max-width: 300px; }
}
@media (max-height: 640px) {
  .hero-title { font-size: 64px; }
  .portrait-wrap { height: 100px; }
  .dossier { padding: 10px 12px; }
  .tagline { display: none; }
}

