506:   updateAttack(dt) {
507:     const a = this.state.attack;
508:     a.t += dt;
509:     const p = a.t / a.dur;
510:     // slight forward lean / movement during attacks
511:     if (a.kind !== 'special' && a.kind !== 'roar') {
512:       const lunge = Math.sin(clamp(p, 0, 1) * Math.PI) * (a.kind === 'heavy' ? 5 : 3);
513:       const f = this.forward;
514:       this.root.position.x += f.x * lunge * dt;
515:       this.root.position.z += f.z * lunge * dt;
516:       this.resolveCollisions(dt, false);
517:     }
518:     if (!a.hitDone && a.t >= a.hit) {
519:       a.hitDone = true;
520:       this.executeHit(a);
521:     }
522:     if (a.kind === 'special' && a.special) this.updateSpecial(dt, a);
523:     if (a.t >= a.dur) {
524:       this.state.attack = null;
525:       this.state.speed = 0;
526:       if (this.activeBeams.length) this.endBeams();
527:     }
528:     this.state.speed = 0;
