544:         target.grabbedBy = this;
545:         target.state.grabbed = true;
546:         target.state.attack = null;
547:         target.state.ragdoll = false;
548:         target.velocity.set(0, 0, 0);
549:         this.game.audio.impact(1.1);
550:         this.game.hud?.toast(`${target.name} GRABBED`, 'info');
551:       }
552:       return;
553:     }
554:     if (a.kind === 'special') {
555:       this.fireSpecial(a);
556:       return;
557:     }
558:     // melee / stomp
559:     const dmg = stats.damage * (1 + (this.state.burn > 0 ? 0.08 : 0));
560:     const result = this.game.melee(this, a.kind, stats);
561:     if (a.kind === 'stomp') {
