          stripe.rotation.x = -Math.PI / 2;
          stripe.position.set(x + i * 2.1, 0.04, z + 14);
          this.group.add(stripe);
          const stripe2 = stripe.clone();
          stripe2.position.z = z - 14;
          this.group.add(stripe2);
