63:.hud button, .hud .ability, .hud .joystick, .hud .mob-btn, .hud .mini-x { pointer-events: auto; }
67:.screen-fx { position: absolute; inset: 0; pointer-events: none; z-index: 5; }
104:  position: fixed; inset: 0; z-index: 200;
