import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.setDefaultTimeout(30000);
const errors = [];
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
page.on('console', (m) => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });

await page.goto('http://localhost:4173/', { waitUntil: 'load', timeout: 45000 });
await page.waitForFunction(() => window.__game?.active === true, null, { timeout: 30000 });

const scenarios = [
  { player: 'godzilla2014', enemy: 'ghidorah' },
  { player: 'godzilla2021', enemy: 'ghidorah' },
  { player: 'godzillaEvolved', enemy: 'ghidorah' },
  { player: 'ghidorah', enemy: 'godzilla2021' },
  { player: 'mechagodzilla', enemy: 'godzilla2021' },
  { player: 'mothra', enemy: 'godzilla2021' },
];

const results = [];
for (const s of scenarios) {
  await page.evaluate(({ player, enemy }) => {
    const g = window.__game;
    g.start({
      mode: 'battle', playerId: player, enemies: [enemy], allies: [],
      weather: 'clear', time: 'day', intro: false, title: '',
    });
    g.paused = false;
    g.introTimer = 0;
    const p = g.player;
    const e = g.monsters.find((m) => m !== p && m.team !== p.team);
    p.root.position.set(0, 0, 60);
    p.yaw = 0;
    p.state.attack = null;
    p.state.ragdoll = false;
    p.state.dead = false;
    p.dead = false;
    p.hp = p.maxHp;
    p.stamina = p.maxStamina;
    p.cooldowns.special = 0;
    e.root.position.set(0, 0, -60);
    e.yaw = Math.PI;
    e.ai = null;
    e.state.attack = null;
    e.state.ragdoll = false;
    e.state.dead = false;
    e.dead = false;
    e.hp = e.maxHp;
    e.balance = e.maxBalance;
    window.__beamTest = { startHp: e.hp, maxHp: e.maxHp, special: p.def.special };
    p.startSpecial();
  }, s);

  await page.waitForTimeout(1400);
  const mid = await page.evaluate(() => {
    const g = window.__game;
    return {
      beams: g.player?.activeBeams?.length ?? 0,
      attacking: !!g.player?.state?.attack,
      attackDur: g.player?.state?.attack?.dur ?? null,
      attackT: g.player?.state?.attack?.t ?? null,
      hp: g.monsters.find((m) => m !== g.player && m.team !== g.player.team)?.hp ?? null,
    };
  });
  await page.waitForTimeout(3400);
  const end = await page.evaluate(() => {
    const g = window.__game;
    const e = g.monsters.find((m) => m !== g.player && m.team !== g.player.team);
    const t = window.__beamTest;
    return {
      hp: e?.hp ?? null,
      maxHp: t?.maxHp ?? null,
      damage: t ? Math.round((t.startHp - e.hp) * 10) / 10 : null,
      beams: g.player?.activeBeams?.length ?? 0,
      attacking: !!g.player?.state?.attack,
      attackDur: g.player?.state?.attack?.dur ?? null,
      special: t?.special ? {
        name: t.special.name, type: t.special.type, damage: t.special.damage,
        range: t.special.range, beamDuration: t.special.beamDuration ?? null,
      } : null,
    };
  });
  results.push({ scenario: `${s.player} -> ${s.enemy}`, mid, end });
  console.log(JSON.stringify(results.at(-1)));
}

console.log('ERRORS', JSON.stringify(errors, null, 2));
await browser.close();

