import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.setDefaultTimeout(30000);
const errors = [];
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
page.on('console', (m) => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });

await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 45000 });
await page.waitForFunction(() => window.__game?.active === true, null, { timeout: 30000 });

const scenarios = [
  { player: 'godzilla2014', enemy: 'ghidorah' },
  { player: 'godzilla2021', enemy: 'ghidorah' },
  { player: 'godzillaEvolved', enemy: 'ghidorah' },
  { player: 'ghidorah', enemy: 'godzilla2021' },
  { player: 'mechagodzilla', enemy: 'godzilla2021' },
  { player: 'mothra', enemy: 'godzilla2021' },
  { player: 'godzilla2019', enemy: 'ghidorah' },
];

const results = [];
for (const s of scenarios) {
  const result = await page.evaluate(({ player, enemy }) => {
    const g = window.__game;
    g.start({
      mode: 'battle', playerId: player, enemies: [enemy], allies: [],
      weather: 'clear', time: 'day', intro: false, title: '',
    });
    g.paused = false;
    g.introTimer = 0;
    g.input.enabled = false;
    const p = g.player;
    const e = g.monsters.find((m) => m !== p && m.team !== p.team);
    p.root.position.set(0, 0, 60);
    p.yaw = 0;
    p.state.attack = null;
    p.state.ragdoll = false;
    p.state.dead = false;
    p.dead = false;
    p.hp = p.maxHp;
    p.stamina = p.maxStamina;
    p.cooldowns.special = 0;
    p.balance = p.maxBalance;
    e.root.position.set(0, 0, -60);
    e.yaw = Math.PI;
    e.ai = null;
    e.state.attack = null;
    e.state.ragdoll = false;
    e.state.dead = false;
    e.dead = false;
    e.hp = e.maxHp;
    e.balance = e.maxBalance;
    e.velocity.set(0, 0, 0);
    const startHp = e.hp;
    const maxHp = e.maxHp;
    const special = {
      name: p.def.special.name, type: p.def.special.type, damage: p.def.special.damage,
      range: p.def.special.range, beamDuration: p.def.special.beamDuration ?? null,
      beamWidth: p.def.special.beamWidth ?? null, beamDamage: p.def.special.beamDamage ?? null,
      beamTick: p.def.special.beamTick ?? null,
    };
    const step = (seconds) => {
      const frames = Math.round(seconds * 60);
      for (let i = 0; i < frames; i++) g.update(1 / 60);
    };
    p.startSpecial();
    step(1.4);
    const mid = {
      beams: p.activeBeams.length,
      attackT: Math.round(p.state.attack.t * 100) / 100,
      attackDur: p.state.attack.dur,
      enemyHp: Math.round(e.hp * 10) / 10,
    };
    step(3.6);
    return {
      scenario: `${player} -> ${enemy}`,
      special,
      mid,
      end: {
        enemyHp: Math.round(e.hp * 10) / 10,
        damage: Math.round((startHp - e.hp) * 10) / 10,
        maxHp,
        beams: p.activeBeams.length,
        attacking: !!p.state.attack,
      },
    };
  }, s);
  results.push(result);
  console.log(JSON.stringify(result));
}

console.log('ERRORS', JSON.stringify(errors, null, 2));
await browser.close();

