import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
page.on('console', (m) => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 45000 });
await page.waitForFunction(() => window.__game?.active === true, null, { timeout: 30000 });

const result = await page.evaluate(() => {
  const g = window.__game;
  g.start({
    mode: 'battle', playerId: 'godzillaEvolved', enemies: [], allies: [],
    weather: 'clear', time: 'day', intro: false, title: '',
  });
  g.paused = false;
  g.introTimer = 0;
  g.input.enabled = false;
  const p = g.player;
  const b = g.city.buildings.find((x) => !x.destroyed && x.height > 60);
  if (!b) return { error: 'no building' };
  p.root.position.set(b.x, 0, b.z + 150);
  p.yaw = 0;
  p.state.attack = null;
  p.stamina = p.maxStamina;
  p.cooldowns.special = 0;
  const before = { hp: b.hp, maxHp: b.maxHp, destroyed: b.destroyed, cityDestroyed: g.city.destructionCount };
  p.startSpecial();
  for (let i = 0; i < 60 * 5; i++) g.update(1 / 60);
  return {
    before,
    after: { hp: Math.round(b.hp), maxHp: b.maxHp, destroyed: b.destroyed, cityDestroyed: g.city.destructionCount },
    building: { x: Math.round(b.x), z: Math.round(b.z), height: Math.round(b.height) },
  };
});
console.log(JSON.stringify(result, null, 2));
console.log('ERRORS', JSON.stringify(errors, null, 2));
await browser.close();

