import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 45000 });
await page.waitForFunction(() => window.__game?.active === true, null, { timeout: 30000 });

for (const [player, enemy, name] of [
  ['godzillaEvolved', 'ghidorah', 'evolved'],
  ['ghidorah', 'godzilla2021', 'ghidorah'],
]) {
  await page.evaluate(({ player, enemy }) => {
    const g = window.__game;
    g.start({
      mode: 'battle', playerId: player, enemies: [enemy], allies: [],
      weather: 'clear', time: 'day', intro: false, title: '',
    });
    g.paused = false;
    g.introTimer = 0;
    g.input.enabled = false;
    const p = g.player;
    const e = g.monsters.find((m) => m !== p && m.team !== p.team);
    p.root.position.set(0, 0, 100);
    p.yaw = 0;
    p.state.attack = null;
    p.stamina = p.maxStamina;
    p.cooldowns.special = 0;
    e.root.position.set(0, 0, -80);
    e.yaw = Math.PI;
    e.ai = null;
    e.hp = e.maxHp;
    e.balance = e.maxBalance;
    p.startSpecial();
    for (let i = 0; i < 150; i++) g.update(1 / 60);
    g.renderer.render(g.scene, g.camera);
  }, { player, enemy });
  await page.waitForTimeout(300);
  await page.screenshot({ path: `/tmp/opencode/beam-${name}.png` });
}
await browser.close();

